/* ---------- extra target shapes ---------- */

.hit-tap.tap-screen-connector { right: 8%; top: 21%; }
.hit-tap.tap-battery-connector { left: 50%; top: 53%; }

.hit-scrub {
  border-radius: 10px;
  border: 1px dashed rgba(255, 190, 110, .28);
  background: repeating-linear-gradient(115deg, rgba(255, 180, 80, .03) 0 6px, transparent 6px 12px);
}
.hit-scrub.armed { border-color: rgba(255, 190, 110, .6); background: repeating-linear-gradient(115deg, rgba(255, 180, 80, .08) 0 6px, transparent 6px 12px); }
.hit-scrub.scrub-front { left: 6%; right: 6%; top: 19%; bottom: 12%; }
.hit-scrub.scrub-back { left: 8%; right: 8%; top: 12%; bottom: 14%; border-radius: 14px; }

.hit-hold {
  inset: 3.4%;
  border-radius: 15.5% / 7%;
  border: 1px dashed rgba(255, 190, 110, .35);
}
.hit-hold.armed { border-color: rgba(255, 190, 110, .7); background: rgba(255, 170, 70, .05); }
.hit-hold::before, .hit-hold::after { border-radius: 15.5% / 7%; }
.hold-ring {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 62px;
  height: 62px;
  margin: -31px 0 0 -31px;
  border-radius: 50%;
  background: conic-gradient(rgba(255, 180, 87, .9) calc(var(--p, 0) * 360deg), rgba(255, 255, 255, .12) 0);
  mask: radial-gradient(circle, transparent 56%, #000 58% 70%, transparent 72%);
  -webkit-mask: radial-gradient(circle, transparent 56%, #000 58% 70%, transparent 72%);
  filter: drop-shadow(0 0 8px rgba(255, 180, 87, .4));
  pointer-events: none;
}

.phone.open .hit-remove.rem-screen {
  transform: translate(-64%, -10%) rotate(-13deg) scale(.72);
  transform-origin: 50% 46%;
}
.phone.back-open .hit-remove.rem-backglass {
  transform: translate(-16%, -5%) rotate(-3deg) scale(.98);
  transform-origin: 50% 50%;
}

.tray-chip.ready {
  border-color: rgba(125, 227, 193, .55);
  box-shadow: 0 0 0 1px rgba(125, 227, 193, .12), 0 0 18px rgba(125, 227, 193, .18);
  animation: chipIn .35s var(--ease-spring), chipReady 1.6s .35s ease-in-out infinite;
}
.drag-ghost.over .chip-visual { box-shadow: 0 0 0 2px rgba(125, 227, 193, .9), 0 0 20px rgba(125, 227, 193, .4); }

@keyframes chipReady {
  0%, 100% { box-shadow: 0 0 0 1px rgba(125, 227, 193, .12), 0 0 12px rgba(125, 227, 193, .12); }
  50% { box-shadow: 0 0 0 1px rgba(125, 227, 193, .3), 0 0 24px rgba(125, 227, 193, .26); }
}

.phone.screen-closable .screen {
  cursor: pointer;
  box-shadow:
    inset 0 0 0 1px rgba(255, 215, 155, .5),
    0 0 0 3px rgba(255, 180, 87, .22),
    0 0 26px rgba(255, 170, 70, .28),
    0 26px 44px rgba(0, 0, 0, .5);
  animation: closableGlow 1.6s ease-in-out infinite;
}
@keyframes closableGlow {
  0%, 100% { filter: brightness(1); }
  50% { filter: brightness(1.22); }
}

.phone.repaired .screen-alert,
.phone.repaired .cracked,
.phone.repaired .back-cracked { display: none; }

.test-result, .charge-result {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 0 14px;
  color: var(--cream);
  text-align: center;
  animation: resultIn .35s var(--ease-spring);
}
.test-result .tr-ico { font-size: 26px; line-height: 1.1; filter: drop-shadow(0 2px 6px rgba(0, 0, 0, .5)); }
.test-result b, .charge-result b {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .14em;
  color: var(--mint);
}
.test-result small, .charge-result small {
  font-family: var(--mono);
  font-size: 4.5px;
  letter-spacing: .06em;
  color: rgba(255, 255, 255, .5);
  line-height: 1.5;
}
.charge-result span { font-size: 28px; color: var(--amber); line-height: 1; }
.charge-result b { color: var(--amber); font-size: 7px; }
@keyframes resultIn {
  from { opacity: 0; transform: scale(.9); }
  to { opacity: 1; transform: scale(1); }
}

.confetti-layer { z-index: 120; }

@media (max-height: 660px) {
  .parts-tray { width: 61px; bottom: 23%; padding: 5px 4px 6px; }
  .tray-body { min-height: 66px; }
  .chip-visual { height: 40px; }
  .hit-tag { font-size: 5px; padding: 3px 5px; }
  .cable-wrap { height: 118px; }
  .cable-wire { height: 84px; }
  .hold-ring { width: 52px; height: 52px; margin: -26px 0 0 -26px; }
}

