/* ---------- summary ---------- */

.summary-screen {
  background:
    radial-gradient(110% 55% at 50% -6%, rgba(125, 227, 193, .12), transparent 58%),
    radial-gradient(100% 55% at 50% 108%, rgba(255, 158, 60, .08), transparent 66%),
    var(--bg);
}
.summary-body {
  flex: 1;
  min-height: 0;
  overflow: hidden;
  position: relative;
  padding: 6px var(--gutter) 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
}
.fixed-stamp {
  position: absolute;
  right: 18px;
  top: 8px;
  padding: 6px 9px;
  border: 2px solid rgba(125, 227, 193, .45);
  border-radius: 5px;
  color: rgba(125, 227, 193, .75);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .18em;
  transform: rotate(7deg);
  opacity: .8;
  animation: stampIn .5s .15s var(--ease-spring) both;
}
.summary-top {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 4px;
}
.summary-who { min-width: 0; }
.summary-eyebrow {
  display: block;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .16em;
  color: var(--mint);
  margin-bottom: 2px;
}
.summary-top h2 {
  margin: 0;
  font-size: 25px;
  line-height: 1;
  letter-spacing: -.035em;
  font-weight: 800;
}
.summary-stars {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 4px 0 2px;
  color: #4a3d2c;
}
.summary-stars .ico {
  width: 32px;
  height: 32px;
  transition: color .3s;
}
.summary-stars .ico.on {
  color: var(--amber);
  filter: drop-shadow(0 3px 6px rgba(255, 170, 70, .3));
  animation: starPop .5s var(--ease-spring) both;
}
.summary-stars .ico.on:nth-child(2) { animation-delay: .12s; }
.summary-stars .ico.on:nth-child(3) { animation-delay: .24s; }
.summary-quote {
  margin: 0;
  text-align: center;
  font-size: 12.5px;
  line-height: 1.45;
  color: var(--muted);
  max-width: 310px;
  min-height: 18px;
}
.receipt {
  width: 100%;
  margin-top: 2px;
  padding: 12px 15px 10px;
  border-radius: 16px;
  color: var(--paper-ink);
  background:
    radial-gradient(120% 80% at 20% 0%, #fff8e9, transparent 52%),
    linear-gradient(165deg, var(--paper), var(--paper-2));
  box-shadow: 0 14px 28px rgba(0, 0, 0, .32), inset 0 1px 0 rgba(255, 255, 255, .7);
  transform: rotate(-.35deg);
  animation: receiptIn .5s .1s var(--ease-out) both;
}
.receipt-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 4px 0;
  font-size: 12px;
}
.receipt-row span { color: #6c5a43; }
.receipt-row b { font-weight: 700; color: #332617; }
.perfect-row b { color: #b76a1d; }
.receipt-rule {
  height: 1px;
  margin: 6px 0;
  background: repeating-linear-gradient(to right, rgba(80, 56, 30, .3) 0 5px, transparent 5px 10px);
}
.receipt-total { padding: 2px 0 5px; }
.receipt-total span { font-weight: 700; color: #332617; font-size: 13px; }
.receipt-total b { font-size: 23px; letter-spacing: -.04em; color: #2a1e0e; }
.receipt-meta {
  display: flex;
  justify-content: space-between;
  border-top: 1px dashed rgba(80, 56, 30, .24);
  padding-top: 7px;
  font-family: var(--mono);
  font-size: 6.2px;
  letter-spacing: .1em;
  color: #8a765d;
}
.receipt-meta b { color: #4a3a26; margin-left: 4px; font-size: 8px; }
.summary-next {
  margin: 0;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: .14em;
  color: var(--muted-2);
  text-align: center;
  text-transform: uppercase;
}

@keyframes starPop {
  0% { transform: scale(.2) rotate(-24deg); opacity: 0; }
  70% { transform: scale(1.16) rotate(4deg); opacity: 1; }
  100% { transform: scale(1) rotate(0); opacity: 1; }
}
@keyframes stampIn {
  from { opacity: 0; transform: rotate(16deg) scale(1.7); }
  to { opacity: .8; transform: rotate(7deg) scale(1); }
}
@keyframes receiptIn {
  from { opacity: 0; transform: rotate(-2deg) translateY(14px); }
  to { opacity: 1; transform: rotate(-.35deg) translateY(0); }
}

/* ---------- finale ---------- */

.finale-screen {
  background:
    radial-gradient(90% 55% at 50% 12%, rgba(255, 170, 70, .17), transparent 60%),
    radial-gradient(90% 50% at 50% 110%, rgba(80, 165, 140, .12), transparent 70%),
