  text-align: center;
  gap: 6px;
  position: relative;
}
.finale-eyebrow {
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .24em;
  color: var(--muted-2);
}
.trophy {
  position: relative;
  width: 100px;
  height: 100px;
  display: grid;
  place-items: center;
  margin: 4px 0 2px;
}
.trophy .ico {
  width: 70px;
  height: 70px;
  color: var(--amber);
  filter: drop-shadow(0 6px 14px rgba(255, 160, 50, .4));
  animation: trophyFloat 4s ease-in-out infinite;
  z-index: 2;
}
.trophy-glow {
  position: absolute;
  inset: 5px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 180, 87, .3), transparent 67%);
  filter: blur(8px);

  position: relative;
}
.finale-stats > div + div::before {
  content: '';
  position: absolute;
  left: 0; top: 18%;
  bottom: 18%;
  width: 1px;
  background: var(--line);
}
.finale-stats span {
  font-family: var(--mono);
  font-size: 5.8px;
  letter-spacing: .12em;
  color: var(--muted-2);
}
.finale-stats b {
  font-size: 17px;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--cream);
}
.finale-note {
  margin-top: 6px;
  font-size: 10px;
