 const wait=ms=>new Promise(r=>setTimeout(r,ms)); const pe=(el,t,x,y)=>el.dispatchEvent(new PointerEvent(t,{bubbles:true,cancelable:true,clientX:x,clientY:y,pointerId:11,pointerType:"touch",isPrimary:true})); const c=el=>{const r=el.getBoundingClientRect();return [r.left+r.width/2,r.top+r.height/2]};
 const tool=()=>{document.querySelector("#helpBtn").click(); const b=document.querySelector(".tool.hinted"); if(b) b.click();};
 for(let g=0; g<14; g++){
   if(!document.querySelector("#cableWrap").hidden) return "plug";
   const chip=document.querySelector("#newPartChip");
   if(chip && !chip.hidden && chip.getBoundingClientRect().width>0){ tool(); await wait(120); const slot=document.querySelector(".install-slot.show"); if(slot){let [cx,cy]=c(chip),[sx,sy]=c(slot); pe(chip,"pointerdown",cx,cy); for(let i=1;i<=8;i++){pe(window,"pointermove",cx+(sx-cx)*i/8,cy+(sy-cy)*i/8); await wait(30);} pe(window,"pointerup",sx,sy);} await wait(1700); continue; }
   const hit=document.querySelector("#targetsFront .hit, #targetsBack .hit");
