     if(cls.includes("hit-screw")){ for(const s of [...document.querySelectorAll("#targetsFront .hit")]){let [x,y]=c(s); pe(s,"pointerdown",x,y); pe(s,"pointerup",x,y); await wait(100);} }
     else if(cls.includes("hit-heat")){ let [x,y]=c(hit); pe(hit,"pointerdown",x,y); for(let i=0;i<14;i++){pe(hit,"pointermove",x+(i%2?70:-70),y); await wait(25);} pe(hit,"pointerup",x,y); }
     else if(cls.includes("hit-pry")){ let [x,y]=c(hit); pe(hit,"pointerdown",x,y); for(let i=1;i<=8;i++){pe(hit,"pointermove",x,y-i*10); await wait(25);} pe(hit,"pointerup",x,y-80); }
     else if(cls.includes("hit-tap")){ let [x,y]=c(hit); pe(hit,"pointerdown",x,y); pe(hit,"pointerup",x,y); }
     else if(cls.includes("hit-remove")){ let [x,y]=c(hit); pe(hit,"pointerdown",x,y); for(let i=1;i<=6;i++){pe(window,"pointermove",x-i*15,y+i*18); await wait(25);} pe(window,"pointerup",x-90,y+110); }
     await wait(1700); continue;
   }
   const badge=document.querySelector("#screenBadge");
   if(badge && !badge.hidden){ let [x,y]=c(document.querySelector("#deviceScreen")); pe(document.querySelector("#deviceScreen"),"pointerdown",x,y); await wait(1400); continue; }
   await wait(300);
 }
 return "guard";
}'; sleep .4; playwright-cli screenshot --filename=screenshots/charge-plug.jpg

