playwright-cli resize 390 844; playwright-cli eval '() => { localStorage.clear(); location.reload(); return 1 }'; sleep .8; playwright-cli eval '() => { [...document.querySelectorAll("button")].find(x=>x.textContent.includes("Open the shop"))?.click(); return 1 }'; sleep .4; playwright-cli eval '() => { [...document.querySelectorAll("button")].find(x=>x.textContent.includes("Start repair"))?.click(); return 1 }'; sleep .7; playwright-cli eval '() => {
  window.__wait=ms=>new Promise(r=>setTimeout(r,ms));
  window.__pe=(el,t,x,y)=>el.dispatchEvent(new PointerEvent(t,{bubbles:true,cancelable:true,clientX:x,clientY:y,pointerId:21,pointerType:"touch",isPrimary:true}));
  window.__c=el=>{const r=el.getBoundingClientRect();return [r.left+r.width/2,r.top+r.height/2]};
  window.__autoDay2=async function(){
    const wait=window.__wait, pe=window.__pe, c=window.__c;
    const pickTool=async()=>{document.querySelector("#helpBtn").click(); await wait(70); document.querySelector(".tool.hinted")?.click(); await wait(90);};
    const hits=()=>[...document.querySelectorAll("#targetsFront .hit, #targetsBack .hit")].filter(h=>h.getBoundingClientRect().width>0);
    for(let guard=0; guard<22; guard++){
      if(document.querySelector("#screen-summary.is-active")) return "summary";
      if(document.querySelector("#screen-finale.is-active")) return "finale";
      const chip=document.querySelector("#newPartChip");
      if(chip && !chip.hidden && chip.getBoundingClientRect().width>0){ await pickTool(); const slot=document.querySelector(".install-slot.show"); if(slot){let [cx,cy]=c(chip),[sx,sy]=c(slot); pe(chip,"pointerdown",cx,cy); for(let i=1;i<=8;i++){pe(window,"pointermove",cx+(sx-cx)*i/8,cy+(sy-cy)*i/8); await wait(30);} pe(window,"pointerup",sx,sy);} await wait(1750); continue; }
      if(!document.querySelector("#cableWrap").hidden){ const cable=document.querySelector("#cable"); let [cx,cy]=c(cable); pe(cable,"pointerdown",cx,cy); for(let i=1;i<=8;i++){pe(window,"pointermove",cx,cy-i*10); await wait(25);} pe(window,"pointerup",cx,cy-80); await wait(2100); continue; }
      const hit=hits()[0];
      if(hit){ await pickTool(); const cls=hit.className;
        if(cls.includes("hit-screw")){ for(const s of hits()){let [x,y]=c(s); pe(s,"pointerdown",x,y); pe(s,"pointerup",x,y); await wait(110);} }
        else if(cls.includes("hit-heat")){ let [x,y]=c(hit); pe(hit,"pointerdown",x,y); for(let i=0;i<16;i++){pe(hit,"pointermove",x+(i%2?75:-75),y); await wait(25);} pe(hit,"pointerup",x,y); }
        else if(cls.includes("hit-pry")){ let [x,y]=c(hit); pe(hit,"pointerdown",x,y); for(let i=1;i<=8;i++){pe(hit,"pointermove",x,y-i*10); await wait(25);} pe(hit,"pointerup",x,y-80); }
        else if(cls.includes("hit-tap")){ let [x,y]=c(hit); pe(hit,"pointerdown",x,y); pe(hit,"pointerup",x,y); }
        else if(cls.includes("hit-remove")){ let [x,y]=c(hit); pe(hit,"pointerdown",x,y); for(let i=1;i<=6;i++){pe(window,"pointermove",x-i*15,y+i*18); await wait(25);} pe(window,"pointerup",x-90,y+110); }
        else if(cls.includes("hit-scrub")){ const spots=[...document.querySelectorAll("#phone .corrosion, #phone .adhesive")].filter(s=>s.getBoundingClientRect().width>0); let [x,y]=c(hit); pe(hit,"pointerdown",x,y); for(const s of spots){let [sx,sy]=c(s); pe(hit,"pointermove",sx,sy); await wait(130);} pe(hit,"pointerup",x,y); }
        else if(cls.includes("hit-hold")){ let [x,y]=c(hit); pe(hit,"pointerdown",x,y); await wait(1250); pe(hit,"pointerup",x,y); }
        else { let [x,y]=c(hit); pe(hit,"pointerdown",x,y); pe(hit,"pointerup",x,y); }
        await wait(1750); continue;
      }
      const test=document.querySelector(".test-target");
      if(test){ test.click(); await wait(2800); continue; }
      const badge=document.querySelector("#screenBadge");
      if(badge && !badge.hidden){ let [x,y]=c(document.querySelector("#deviceScreen")); pe(document.querySelector("#deviceScreen"),"pointerdown",x,y); await wait(1450); continue; }
      await wait(350);
    }
    return "guard";
  };
  return "ready";
}'; sleep .2; playwright-cli eval 'async () => await window.__autoDay2()'

